const menuButton=document.querySelector('.menu-toggle');const nav=document.querySelector('.site-nav');
if(menuButton&&nav){menuButton.addEventListener('click',()=>{const open=menuButton.getAttribute('aria-expanded')!=='true';menuButton.setAttribute('aria-expanded',String(open));menuButton.setAttribute('aria-label',open?'Close navigation':'Open navigation');nav.classList.toggle('open',open)});nav.addEventListener('click',ev=>{if(ev.target.closest('a')){menuButton.setAttribute('aria-expanded','false');nav.classList.remove('open')}})}
const chips=[...document.querySelectorAll('[data-filter]')];const search=document.querySelector('#article-search');const cards=[...document.querySelectorAll('#article-results .article-card')];const empty=document.querySelector('#empty-state');let activeFilter='All essays';function filterCards(){const q=(search?.value||'').toLowerCase().trim();let count=0;for(const card of cards){const matches=(activeFilter==='All essays'||card.dataset.category===activeFilter)&&(!q||card.dataset.search.includes(q));card.hidden=!matches;if(matches)count++}if(empty)empty.hidden=count!==0}
for(const chip of chips)chip.addEventListener('click',()=>{activeFilter=chip.dataset.filter;for(const c of chips){const on=c===chip;c.classList.toggle('active',on);c.setAttribute('aria-pressed',String(on))}filterCards()});if(search)search.addEventListener('input',filterCards);
